            for i, patch in enumerate(possible_patches):
                print(f"Patch {i+1}:")
                display(patch.annotated_image)
                # print boxes detected within this patch (if returned)
                if i < len(possible_boxes):
                    print(f"Boxes in patch {i+1}:", possible_boxes[i])
                else:
                    print(f"No boxes info for patch {i+1}.")
    except Exception as e2:
        print("sliding_window_detection also raised an exception:", repr(e2))
        print("Cannot proceed with automatic detection; please check the environment or provide guidance.")
